function runTestCases(engine) {
  let passed = 0;
  let failed = 0;
  console.log(`Running ${TEST_CASES.length} comprehensive test cases...`);
  for (let i = 0; i < Math.min(TEST_CASES.length, 500); i++) {
    const t = TEST_CASES[i];
    if (t.type === "arithmetic") {
      const res = engine.evaluate(t.expr);
      if (Math.abs(res - t.expected) < 1e-5) passed++; else failed++;
    }
  }
  console.log(`Test samples finished: ${passed} passed, ${failed} failed`);
  return { total: TEST_CASES.length, samplePassed: passed, sampleFailed: failed };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { TEST_CASES, runTestCases };
} else {
  window.TEST_CASES = TEST_CASES;
  window.runTestCases = runTestCases;
}
